#!/bin/bash
# AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
#
# Shell script to execute Docker container with volume mapping
# Maps current directory to /workspace in container
#
# Mounted into the container:
#   $CURRENT_DIR                     -> /workspace        (binary + csv)
#   ${PI_SENSOR_STAGING:-/srv/pi_sensor} -> /srv/pi_sensor  (staging csv)
#   ~/.pi_sensor.ini (if it exists)  -> same path         (config)
#   /run/mysqld (if it exists)       -> /run/mysqld       (unix socket)
#
# Usage (from collectdata/):
#   ./run_container/run_container.sh                        # import
#   ./run_container/run_container.sh ./import_temperatures --dry-run -v
#   ./run_container/run_container.sh ./import_temperatures -d

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CURRENT_DIR="$(pwd)"
IMAGE_NAME="pi-sensor-run-container"
CONTAINER_NAME="pi-sensor-run"

MOUNTS=()
MOUNTS+=( -v "$CURRENT_DIR:/workspace" )

# the container runs with the host uid, which has no passwd entry in the image:
# "~" in the config would not resolve without this
MOUNTS+=( -v "/etc/passwd:/etc/passwd:ro" )

STAGING_DIR="${PI_SENSOR_STAGING:-/srv/pi_sensor}"
if [ -d "$STAGING_DIR" ] ; then
	MOUNTS+=( -v "$STAGING_DIR:/srv/pi_sensor" )
fi

CONFIG_FILE="${PI_SENSOR_CONFIG:-$HOME/.pi_sensor.ini}"
if [ -f "$CONFIG_FILE" ] ; then
	MOUNTS+=( -v "$CONFIG_FILE:$CONFIG_FILE" )
fi

if [ -d /run/mysqld ] ; then
	MOUNTS+=( -v "/run/mysqld:/run/mysqld" )
fi

if [ "$#" -eq 0 ] ; then
	set -- ./import_temperatures -v
fi

echo "Building Docker image..."
docker build -t "$IMAGE_NAME" "$SCRIPT_DIR"

echo "Running container with volume mapping..."
echo "  Image: $IMAGE_NAME"
echo "  Container: $CONTAINER_NAME"
echo "  Local directory: $CURRENT_DIR"
echo "  Container mount: /workspace"

docker run --rm -t \
  --user $(id -u):$(id -g) \
  -e HOME="$HOME" \
  --name "$CONTAINER_NAME" \
  "${MOUNTS[@]}" \
  -w /workspace \
  "$IMAGE_NAME" \
  /bin/bash -c "$*"

echo "Container execution completed."
